import csv, os, datetime as dt
from collections import defaultdict
p = os.path.join(os.environ["PANTHEON_PROJECTS"], "sales/weekly.csv")
rows = list(csv.DictReader(open(p, newline="", encoding="utf-8-sig")))
def day(s):
    try: return dt.date.fromisoformat((s or "")[:10])
    except ValueError: return None
date_col = next(c for c in rows[0] if all(day(r[c]) for r in rows[:20]))
today = dt.date.today(); this = today - dt.timedelta(days=today.weekday() + 7)
weeks = [this - dt.timedelta(weeks=i) for i in range(6)]
by = defaultdict(lambda: defaultdict(float)); n = defaultdict(int)
for r in rows:
    d = day(r[date_col]); w = d - dt.timedelta(days=d.weekday())
    n[w] += 1
    for m in ["revenue", "orders"]: by[m][w] += float(r[m] or 0)
for m in ["revenue", "orders"]:
    t, l = by[m][weeks[0]], by[m][weeks[1]]; avg = sum(by[m][w] for w in weeks[1:5]) / 4
    print(m, t, l, round((t - l) / l * 100, 1) if l else None, avg, [n[w] for w in weeks[:5]])
    if l and abs(t - l) / l > 0.10:
        for col in [c for c in rows[0] if c not in (date_col, "revenue", "orders")]:
            ch = defaultdict(float)
            for r in rows:
                w = day(r[date_col]) - dt.timedelta(days=day(r[date_col]).weekday())
                if w == weeks[0]: ch[r[col]] += float(r[m] or 0)
                if w == weeks[1]: ch[r[col]] -= float(r[m] or 0)
            print("  by", col, sorted(ch.items(), key=lambda kv: -abs(kv[1]))[:3])

